import { merge } from 'lodash-es';

import { defaultAxisConfig } from '../constants/defaults.js';
import type {
  XYChartAxisProps,
  XYChartConfiguration,
  XYChartHeatmapSeriesProps,
  XYChartSlots,
} from '../types/xy-chart.js';

function getAxes(
  axisSlots: XYChartAxisProps[],
  series: XYChartHeatmapSeriesProps[],
) {
  let axesConfig: XYChartAxisProps[] = [];
  const matchingIds = new Set();

  axisSlots.forEach((axis) => {
    const hasMatchingSeriesId = series.find(
      (series) => series.xAxisId === axis.id,
    );
    const hasUniqueId = !matchingIds.has(axis.id);

    if (hasMatchingSeriesId && hasUniqueId) {
      matchingIds.add(axis.id);
      axesConfig = [...axesConfig, { ...defaultAxisConfig, ...axis }];
    }
  });

  return axesConfig;
}

/**
 * Creates a XY chart configuration merging the configuration
 * provided in the context config, slots, and defaults.
 * @param slots - xy chart slots
 */
export function createXYChartConfiguration(
  slots: XYChartSlots,
): XYChartConfiguration {
  const heatmapSeries = getHeatmapSeries(slots.heatmapSeries);

  const axes = getAxes(slots.axes, heatmapSeries);

  return { heatmapSeries, axes };
}

function getHeatmapSeries(slot: XYChartHeatmapSeriesProps[]) {
  return merge([], slot);
}
